    if (P &gt; 0.1 && P &lt; K_harvest * 1.5) {
      points.push({t: t, P: P});
      const dP = k_harvest * P * (1 - P/K_harvest) - c_harvest;
      P += dP * dt;
    } else {
      break;
    }
  }
  return points;
