          width: 2
        }
      },
      name: `Inicio ${idx + 1}`,
      showlegend: false,
      hovertemplate: 'Inicio&lt;br&gt;x: %{x:.2f}&lt;br&gt;y: %{y:.2f}&lt;br&gt;z: %{z:.2f}&lt;extra&gt;&lt;/extra&gt;'
    });
  });

  // Layout de Plotly con estilo profesional
  const layout = {
    title: {
      text: config.titulo || 'Sistema 3D',
      font: {size: 20, family: 'Arial, sans-serif', color: '#2c3e50'}
    },
    scene: {
      xaxis: {
        title: 'x',
        gridcolor: '#ecf0f1',
        showbackground: true,
        backgroundcolor: '#fafafa'
      },
      yaxis: {
        title: 'y',
        gridcolor: '#ecf0f1',
        showbackground: true,
        backgroundcolor: '#fafafa'
      },
      zaxis: {
        title: 'z',
        gridcolor: '#ecf0f1',
        showbackground: true,
        backgroundcolor: '#fafafa'
      },
      camera: {
        eye: {x: 1.8, y: -1.8, z: 0.8}
      },
      aspectmode: 'cube'
    },
    paper_bgcolor: 'white',
    plot_bgcolor: 'white',
    margin: {l: 0, r: 0, t: 40, b: 0},
    showlegend: true,
    legend: {
      x: 0.02,
