      bgcolor: 'rgba(255,255,255,0.8)',
      bordercolor: '#bdc3c7',
      borderwidth: 1
    },
    hovermode: 'closest'
  };

  // Config de Plotly
  const plotConfig = {
    responsive: true,
    displayModeBar: true,
    displaylogo: false,
    modeBarButtonsToRemove: ['toImage'],
    modeBarButtonsToAdd: [{
      name: 'Resetear vista',
